parameters.jsCode:
// 오늘 날짜를 KST 기준으로 YYYY-MM-DD 포맷.
const now = new Date();
const kst = new Date(now.getTime() + 9 * 60 * 60 * 1000);
const today = kst.toISOString().slice(0, 10);
return [{ json: { today } }];

// Notion 응답을 행 단위로 펼치고, 각 행마다 알림 종류를 분류해 발송 대상을 만든다.
const today = $node["오늘 날짜 계산"].json.today;
const rows = $input.first().json.results || [];
const out = [];

for (const row of rows) {
  const props = row.properties;
  const getText = (p) => (p?.rich_text?.[0]?.plain_text) || '';
  const getTitle = (p) => (p?.title?.[0]?.plain_text) || '';
  const getDate = (p) => p?.date?.start || null;
  const getSelect = (p) => p?.select?.name || null;
  const getNum = (p) => (p?.number ?? null);

  const vendor      = getTitle(props['거래처명']);
  const service     = getText(props['서비스명']);
  const startDate   = getDate(props['계약시작일']);
  const endDate     = getDate(props['계약종료일']);
  const renewalDate = getDate(props['갱신 알림일']);
  const vendorDate  = getDate(props['거래처 통지일']);
  const cost        = getNum(props['견적비용']);
  const registrantId = getText(props['등록 담당자']);
  const ownerId     = getText(props['업무 담당자']);
  const extraIds    = getText(props['추가 알림 대상']);

  const reasons = [];
  if (renewalDate === today) reasons.push('갱신 알림');
  if (vendorDate === today)  reasons.push('거래처 통지');
  if (endDate === today)     reasons.push('계약 만료');
  if (reasons.length === 0)  continue;

  const recipientSet = new Set();
  if (registrantId) recipientSet.add(registrantId);
  if (ownerId) recipientSet.add(ownerId);
  for (const id of extraIds.split(',').map((s) => s.trim()).filter(Boolean)) {
    recipientSet.add(id);
  }

  for (const userId of recipientSet) {
    out.push({
      json: {
        page_id: row.id,
        page_url: row.url,
        vendor,
        service,
        start_date: startDate,
        end_date: endDate,
        cost,
        reasons: reasons.join(' / '),
        recipient_id: userId,
        is_expired_today: endDate === today
      }
    });
  }
}

return out;

